def _check_owner(store, owner):
    if any(j['owner'] == owner and j['state'] == 'failed' and j['quota_held']
           for j in store.rows):
        raise RuntimeError('owner has unresolved failed resources')


def submit(store, owner):
    _check_owner(store, owner)
    job={'id':str(len(store.rows)), 'owner':owner, 'state':'queued', 'resource_id':None, 'quota_held':True}
    store.rows.append(job);store.save();return job

def consume(store, job_id, provider):
    job=next(j for j in store.rows if j['id']==job_id)
    _check_owner(store, job['owner'])
    try:
        rid=provider.create(job['owner'])
        job['resource_id']=rid;store.save()
        provider.configure(rid)
        job['state']='active';store.save()
    except RuntimeError:
        job['state']='failed';store.save();raise

def recover(store, job_id, provider):
    job=next(j for j in store.rows if j['id']==job_id)
    if job['resource_id'] is None:
        return
    provider.delete(job['resource_id'])
    job['quota_held']=False;job['state']='released';store.save()

